#!/bin/bash
function school_admission_evaluation {
    declare -A neighborhood_factors=(["Wealthy"]=3 ["Middle class"]=2 ["Poor"]=1)
    declare -A parent_occupations=(["Doctor"]=3 ["Engineer"]=2 ["Teacher"]=1 ["Unemployed"]=0)

    neighborhood=${1}
    parent_job=${2}

    neighborhood_score=${neighborhood_factors[$neighborhood]:--1}
    parent_job_score=${parent_occupations[$parent_job]:--1}

    acceptance_score=$((neighborhood_score + parent_job_score))

    echo $acceptance_score
}

# Assuming the student_record is passed as two separate arguments
neighborhood="Poor"
parent_job="Unemployed"
score=$(school_admission_evaluation "$neighborhood" "$parent_job")
echo "The acceptance score for neighborhood: $neighborhood, parent_job: $parent_job is $score"

#!/bin/bash
function validate_ip_regex {
    local ip=$1
    if [[ $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
        echo "$ip is a valid IP pattern"
    else
        echo "IP address does not match valid pattern."
    fi
}

validate_ip_regex "192.168.01.01"

