#!/bin/bash

function storePassword {
    local userName=$1
    local Password=$2
    local salt=$(head -c 2 /dev/urandom | xxd -p)
    local hashedPassword=$(echo -n "${salt}${Password}" | sha384sum | awk '{print $1}')
    echo "Updating login for ${userName} with salt = urandom(2)"
    return 0
}

